55	void dfu_boot_img_in_flash(int flashid)
56	{
57	    uint32_t src = sec_config_cache.ftab[flashid].base;
58	    uint32_t dest = sec_config_cache.ftab[flashid].xip_base;
59	    int coreid = DFU_FLASH_IMG_IDX(flashid);
60	    struct image_header_enc *img_hdr = &(sec_config_cache.imgs[coreid]);
61	
62	    if (img_hdr->flags & DFU_FLAG_ENC)
63	    {
64	        uint32_t is_flash = 1;
65	
66	        if (coreid < 2 * CORE_MAX)
67	        {
68	            coreid %= CORE_MAX;
69	            if (coreid == CORE_HCPU || coreid == CORE_BL)
70	            {
71	                ALIGN(4)
72	                static uint8_t dfu_key[DFU_KEY_SIZE];
73	                /** key in plaintext */
74	                ALIGN(4)
75	                static uint8_t dfu_key1[DFU_KEY_SIZE];
76	                if (is_addr_in_nor(dest))
77	                {
78	                    memcpy(dfu_key, img_hdr->key, sizeof(dfu_key));
79	                    sifli_hw_init_xip_key(dfu_key);
80	
81	                    // Setup XIP for decoding and running
82	                    HAL_FLASH_NONCE_CFG(boot_handle, dest, dest + img_hdr->length, dfu_get_counter(0));
83	                    if (is_flash)
84	                        HAL_FLASH_ALIAS_CFG(boot_handle, dest, img_hdr->length, src - dest);
85	                    HAL_FLASH_AES_CFG(boot_handle, 1);          /* enable on-the-fly decoder */
86	                }
87	                else
88	                {
89	                    /* copy encrypted key to ram as AES_ACC cannot access flash */
90	                    memcpy(dfu_key, img_hdr->key, sizeof(dfu_key));
91	                    sifli_hw_dec_key(dfu_key, dfu_key1, sizeof(dfu_key1));
92	                    g_flash_read(src, (const int8_t *)dest, img_hdr->length);
93	                    sifli_hw_dec(dfu_key1, (uint8_t *)dest, (uint8_t *)dest, img_hdr->length, 0);
94	                }
95	                run_img(dest);
96	            }
97	        }
98	    }
99	    if (coreid < 2 * CORE_MAX)
100	    {
101	        coreid %= CORE_MAX;
102	        if (coreid == CORE_HCPU || coreid == CORE_BL)
103	        {
104	            if (is_addr_in_nor(dest))
105	                HAL_FLASH_ALIAS_CFG(boot_handle, dest, img_hdr->length, src - dest);
106	            else if (src != dest)
107	                g_flash_read(src, (const int8_t *)dest, img_hdr->length);
108	            run_img(dest);
109	        }
110	    }
111	}
